begin;
create function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',message;end if;end $$;
grant execute on function pg_temp.assert(boolean,text) to authenticated;
insert into auth.users(id,email,is_anonymous) values('fd900000-0000-4000-8000-000000000001','entry-directory@example.invalid',false),('fd910000-0000-4000-8000-000000000001','entry-foreign@example.invalid',false);
set local role authenticated;
select set_config('request.jwt.claim.sub','fd900000-0000-4000-8000-000000000001',true);
select public.setup_business('Disposable financial entry directory','Entries owner');
reset role;
do $$declare w uuid;id uuid;e uuid;d date:=(now() at time zone 'Asia/Dhaka')::date;result jsonb;begin
 select wallet_id into w from public.get_payment_wallets() where type='cash';
 perform pg_temp.assert(public.get_financial_catalog()->'categories' @> '[{"name":"Withdrawal"},{"name":"Expense"},{"name":"Capital"},{"name":"Revenue"},{"name":"Equipment"}]' and jsonb_array_length(public.get_financial_catalog()->'categories')=5,'Public catalog contains exactly the five fixed categories');
 id:=(public.save_financial_type('{"name":"Directory electricity","account":"operating_expense","allocations":{"lpg":70,"stove":30}}')->>'type_id')::uuid;
 e:=(public.record_financial_entry(jsonb_build_object('type_id',id,'expected_revision',1,'wallet_id',w,'amount',100,'date',d,'description','Directory shared invoice'),gen_random_uuid())->>'entry_id')::uuid;
 perform public.record_financial_entry(jsonb_build_object('reversal_of',e,'wallet_id',w,'amount',30,'date',d,'description','Actual returned funds'),gen_random_uuid());
 result:=public.get_financial_entries('{"search":"","category":"","business":"","from":"","to":""}');
 perform pg_temp.assert((result->>'total')::integer=2,'Financial entries include original and actual returned funds');
 perform pg_temp.assert((public.get_wallet_ledger('{"search":"invoice Directory"}')->>'total')::integer=1,'Ledger search matches all words regardless of order');
 perform pg_temp.assert((public.get_wallet_ledger('{"search":"unknown,invoice"}')->>'total')::integer=1,'Ledger comma groups match alternatives');
 perform pg_temp.assert((public.get_wallet_ledger('{"search":"%"}')->>'total')::integer=0,'Ledger treats wildcard input literally');
 result:=public.get_financial_entries('{"category":"expense","business":"stove","search":"shared"}');
 perform pg_temp.assert((result->>'total')::integer=1 and result->'entries'->0->>'category'='expense' and (result->'entries'->0->>'returned')::numeric=30,'Directory filters retain original category, business and returns');
 begin perform public.save_financial_type('{"name":"Rejected extra category","account":"interest_expense","allocations":{"lpg":100}}');raise exception 'FAIL: extra category accepted';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;end;
 perform pg_temp.assert(app_private.analysis_scope('{}')=array[app_private.current_tenant_id()],'Only the trusted organization is a report scope');
end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub','fd910000-0000-4000-8000-000000000001',true);
select public.setup_business('Disposable foreign financial entry directory','Other owner');
select pg_temp.assert((public.get_financial_entries()->>'total')::integer=0,'Foreign organization cannot read financial entries');
reset role;
set constraints all immediate;
select 'PASS: Financial Entries directory, category/business/search filters, original return snapshots, exact five custom categories and organization isolation';
rollback;
